pub fn lis(xs: List[Int]) -> List[Int] {
  let n = xs.len()
  // lens[i]: length of the longest increasing subsequence that starts at i
  var lens: List[Int] = []
  for _u in range(0, n) {
    lens = lens.push(1)
  }
  var i = n - 1
  while i >= 0 {
    var best = 1
    var j = i + 1
    while j < n {
      if xs.get_or(j, 0) > xs.get_or(i, 0) and lens.get_or(j, 0) + 1 > best {
        best = lens.get_or(j, 0) + 1
      }
      j = j + 1
    }
    lens = lens.set(i, best)
    i = i - 1
  }
  var max_len = 0
  for l in lens {
    if l > max_len {
      max_len = l
    }
  }
  // Walk forward: each next element must extend the chain by one and be the
  // smallest such value (the earliest one on ties) to get the smallest sequence.
  var out: List[Int] = []
  var cur = -1
  var need = max_len
  while need > 0 {
    var pick = -1
    var k = cur + 1
    while k < n {
      let fits = cur < 0 or xs.get_or(k, 0) > xs.get_or(cur, 0)
      if fits and lens.get_or(k, 0) == need {
        if pick < 0 or xs.get_or(k, 0) < xs.get_or(pick, 0) {
          pick = k
        }
      }
      k = k + 1
    }
    cur = pick
    out = out.push(xs.get_or(pick, 0))
    need = need - 1
  }
  return out
}
